import sqlite3


def move_appointment_to_archive(appointment_id: int, db_path: str = "clinic.db") -> dict:
    with sqlite3.connect(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO appointments_archive SELECT * FROM appointments WHERE id = ? AND status = 'completed'",
            (appointment_id,),
        )
        if cur.rowcount == 0:
            return {"moved": False, "reason": "not found or not completed"}
        conn.execute("DELETE FROM appointments WHERE id = ?", (appointment_id,))
    return {"moved": True, "appointment_id": appointment_id}

import sqlite3
from datetime import datetime, timedelta

DATABASE_FILE_PATH = "clinic.db"


def summarize_provider_availability(provider_id: int, start_date: str, end_date: str, slot_minutes: int = 30) -> dict:
    first_day_parsed = datetime.strptime(start_date, "%Y-%m-%d").date()
    last_day_parsed = datetime.strptime(end_date, "%Y-%m-%d").date()
    if last_day_parsed < first_day_parsed:
        return {"error": "end_date is before start_date"}

    database_connection = sqlite3.connect(DATABASE_FILE_PATH)
    database_connection.row_factory = sqlite3.Row
    try:
        working_hours_rows = database_connection.execute(
            "SELECT weekday, start_time, end_time FROM provider_hours WHERE provider_id = ?",
            (provider_id,),
        ).fetchall()
        booked_appointment_rows = database_connection.execute(
            "SELECT date(starts_at) AS day, COUNT(*) AS total FROM appointments "
            "WHERE provider_id = ? AND date(starts_at) BETWEEN ? AND ? AND status != 'cancelled' "
            "GROUP BY date(starts_at)",
            (provider_id, start_date, end_date),
        ).fetchall()
    finally:
        database_connection.close()

    working_minutes_by_weekday = {}
    for hours_row in working_hours_rows:
        opening = datetime.strptime(hours_row["start_time"], "%H:%M")
        closing = datetime.strptime(hours_row["end_time"], "%H:%M")
        working_minutes_by_weekday[hours_row["weekday"]] = int((closing - opening).total_seconds() // 60)

    booked_count_by_day = {row["day"]: row["total"] for row in booked_appointment_rows}

    daily_summary_list = []
    current_day = first_day_parsed
    while current_day <= last_day_parsed:
        total_slots_for_day = working_minutes_by_weekday.get(current_day.weekday(), 0) // slot_minutes
        booked_slots_for_day = booked_count_by_day.get(current_day.isoformat(), 0)
        daily_summary_list.append(
            {
                "date": current_day.isoformat(),
                "total_slots": total_slots_for_day,
                "booked_slots": booked_slots_for_day,
                "free_slots": max(total_slots_for_day - booked_slots_for_day, 0),
            }
        )
        current_day += timedelta(days=1)

    return {"provider_id": provider_id, "days": daily_summary_list}
